package org.jlinalg.singlecell;

import java.util.*;

/** Whole original commu.basic.cal_cell_communication calculation on explicit
 * DataFrame-equivalent expression/coordinates and caller-supplied interaction lists.
 * No pickle database, broken cn.call wrapper, package import, plots or paper replay. */
public final class SpyrrowCommunication {
    private SpyrrowCommunication() { }
    public record Counts(List<String> cells,List<String> genes,double[][] expression) {
        public Counts{cells=List.copyOf(cells);genes=List.copyOf(genes);expression=copy(expression);}
        @Override public double[][] expression(){return copy(expression);}
    }
    public record Database(List<String> ligands,List<String> receptors) {
        public Database{ligands=List.copyOf(ligands);receptors=List.copyOf(receptors);}
    }
    public record Pair(int firstRow,int secondRow,String firstCell,String secondCell,String sourceKey,double distance) { }
    public record Interaction(String key,String ligand,String receptor,int ligandColumn,int receptorColumn) { }
    public record Mapping(int sourceRow,String ligand,String receptor,String disposition,String key) { }
    public record Limits(int maximumCells,int maximumGenes,int maximumInteractions,int maximumPairs,long maximumMatrixCells,long maximumOperations) {
        public Limits{require(maximumCells>0&&maximumGenes>0&&maximumInteractions>0&&maximumPairs>0&&maximumMatrixCells>0&&maximumOperations>0,"Positive complete-family capacities required");}
        public static Limits defaults(){return new Limits(100000,100000,1000000,1000000,50000000,1000000000);}
    }
    public record Result(List<Pair> pairs,List<Interaction> interactions,List<String> ligandOrder,List<String> receptorOrder,List<String> columns,double[][] values,List<Mapping> databaseLedger,List<String> duplicateGenes,int trailingLigands,int trailingReceptors,long operations,List<String> warnings) {
        public Result{pairs=List.copyOf(pairs);interactions=List.copyOf(interactions);ligandOrder=List.copyOf(ligandOrder);receptorOrder=List.copyOf(receptorOrder);columns=List.copyOf(columns);values=copy(values);databaseLedger=List.copyOf(databaseLedger);duplicateGenes=List.copyOf(duplicateGenes);warnings=List.copyOf(warnings);}
        @Override public double[][] values(){return copy(values);}
    }
    public static Result analyze(Counts counts,double[] x,double[] y,Database database,double threshold,Limits limits) {
        Objects.requireNonNull(counts);Objects.requireNonNull(database);Objects.requireNonNull(limits);x=x.clone();y=y.clone();require(Double.isFinite(threshold)&&threshold>=0,"Explicit finite nonnegative distance threshold required");int n=counts.cells.size(),g=counts.genes.size();require(n>0&&g>0&&n<=limits.maximumCells&&g<=limits.maximumGenes&&counts.expression.length==n&&x.length==n&&y.length==n,"Complete input axes/capacity mismatch");require((long)n*g<=limits.maximumMatrixCells,"Complete expression matrix capacity exceeded");var cellSet=new HashSet<String>();for(String cell:counts.cells){label(cell);require(!cell.contains("|")&&cellSet.add(cell),"Duplicate or pipe-delimited cell IDs are outside the unambiguous source pair-key profile; no repair");}var firstGene=new HashMap<String,Integer>();var duplicates=new ArrayList<String>();for(int j=0;j<g;j++){String gene=counts.genes.get(j);gene(gene);if(firstGene.putIfAbsent(gene,j)!=null)duplicates.add(gene);}var meter=new Meter(limits.maximumOperations);
        for(int i=0;i<n;i++){require(Double.isFinite(x[i])&&Double.isFinite(y[i]),"Finite source coordinates required; no missing-coordinate repair");require(counts.expression[i].length==g,"Ragged complete expression matrix");for(double value:counts.expression[i]){meter.spend(1);require(Double.isFinite(value)&&value>=0,"Finite nonnegative source expression required; no normalization or repair");}}
        require(database.ligands.size()<=limits.maximumInteractions&&database.receptors.size()<=limits.maximumInteractions,"Complete database capacity exceeded");int shared=Math.min(database.ligands.size(),database.receptors.size());var selected=new LinkedHashMap<String,Interaction>();var ledger=new ArrayList<Mapping>();
        for(int i=0;i<shared;i++){meter.spend(1);String ligand=database.ligands.get(i),receptor=database.receptors.get(i);gene(ligand);gene(receptor);String key=ligand+":"+receptor;if(!firstGene.containsKey(ligand)||!firstGene.containsKey(receptor)){ledger.add(new Mapping(i,ligand,receptor,"source-skips-unmapped-gene",key));continue;}boolean duplicate=selected.containsKey(key);selected.put(key,new Interaction(key,ligand,receptor,firstGene.get(ligand),firstGene.get(receptor)));ledger.add(new Mapping(i,ligand,receptor,duplicate?"source-overwrites-duplicate-key-retains-first-position":"source-first-key",key));}
        var interactions=List.copyOf(selected.values());var ligandInput=interactions.stream().map(Interaction::ligand).toList();var receptorInput=interactions.stream().map(Interaction::receptor).toList();var ligands=SpyrrowSourceSemantics.setOrder(ligandInput);var receptors=SpyrrowSourceSemantics.setOrder(receptorInput);var ligandRows=new LinkedHashMap<String,List<Integer>>();var receptorRows=new LinkedHashMap<String,List<Integer>>();for(String ligand:ligands)ligandRows.put(ligand,new ArrayList<>());for(String receptor:receptors)receptorRows.put(receptor,new ArrayList<>());for(int i=0;i<interactions.size();i++){meter.spend(1);var interaction=interactions.get(i);ligandRows.get(interaction.ligand).add(i);receptorRows.get(interaction.receptor).add(i);}
        require((long)n*(n-1)/2<=meter.maximum-meter.used,"Complete original pair-search operation capacity exceeded before traversal; no partial pairs");var pairs=new ArrayList<Pair>();for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){meter.spend(1);double distance=SpyrrowSourceSemantics.distance(x[i],y[i],x[j],y[j]);if(distance<threshold){require(pairs.size()<limits.maximumPairs,"Complete source pair capacity exceeded");pairs.add(new Pair(i,j,counts.cells.get(i),counts.cells.get(j),counts.cells.get(i)+"|"+counts.cells.get(j),distance));}}
        require(!pairs.isEmpty(),"Original cal_cell_communication fails with IndexError when there are no selected cell pairs; no fabricated empty success");var columns=new ArrayList<String>();for(String suffix:List.of("_a2b","_b2a"))for(var interaction:interactions)columns.add(interaction.key+suffix);for(String suffix:List.of("_al","_ar","_bl","_br"))for(String gene:suffix.endsWith("l")?ligands:receptors)columns.add(gene+suffix);require((long)pairs.size()*columns.size()<=limits.maximumMatrixCells,"Complete retained source output capacity exceeded before allocation");var values=new double[pairs.size()][columns.size()];boolean nonfinite=false;
        for(int i=0;i<pairs.size();i++){var pair=pairs.get(i);double[] first=counts.expression[pair.firstRow],second=counts.expression[pair.secondRow];double[] a=new double[interactions.size()],b=new double[interactions.size()];int at=0;for(int j=0;j<interactions.size();j++){meter.spend(1);var interaction=interactions.get(j);a[j]=Math.sqrt(first[interaction.ligandColumn]*second[interaction.receptorColumn]);b[j]=Math.sqrt(second[interaction.ligandColumn]*first[interaction.receptorColumn]);values[i][at++]=a[j];nonfinite|=!Double.isFinite(a[j])||!Double.isFinite(b[j]);}for(double value:b)values[i][at++]=value;
            for(int family=0;family<4;family++){var rows=(family==0||family==2)?ligandRows:receptorRows;double[] source=(family==0||family==3)?a:b;for(var indices:rows.values()){double sum=0;for(int j:indices){meter.spend(1);sum+=source[j];}values[i][at++]=sum;nonfinite|=!Double.isFinite(sum);}}require(at==columns.size(),"Complete native output family mismatch");
        }
        var warnings=new ArrayList<String>();warnings.add("Source component only: complete commu.basic.cal_cell_communication on explicit caller data. No original pickle database is loaded, no full Spyrrow package/cn.call or plotting execution is admitted, and no paper-specific database/coordinate scaling/normalization/distance threshold is inferred. The published cn.py contains unguarded study code and an undefined nam import-time failure; its call also reads a pickle and ignores group/subset. Spyrrow remains uncredited as a full integration.");warnings.add("Aggregate column order follows explicit little-endian64-bit CPython3.11.17 SipHash13 with PYTHONHASHSEED=0. This does not infer the paper's Python3.10.5 hash seed. Cell pairs retain i<j input order and strict source math.dist<threshold; coincident distinct cells can pair. Both directions and all four ligand/receptor totals are retained.");if(!duplicates.isEmpty())warnings.add("Duplicate gene names are retained: original list.index uses the first matching expression column, not a mean/sum or alias repair.");int trailingLigands=database.ligands.size()-shared,trailingReceptors=database.receptors.size()-shared;if(trailingLigands>0||trailingReceptors>0)warnings.add("Original zip truncates unequal ligand/receptor lists. Unpaired trailing names are retained in the caller Database and explicit counts; they do not contribute interactions.");if(ledger.stream().anyMatch(row->row.disposition.startsWith("source-overwrites")))warnings.add("Duplicate interaction keys overwrite values while retaining first insertion position, matching original dictionaries. All source database rows and dispositions are retained.");if(nonfinite)warnings.add("Finite expression products/sums overflowed to Inf. Raw source-compatible states remain retained; this component admits no downstream analysis and never replaces Inf with zero.");return new Result(pairs,interactions,ligands,receptors,columns,values,ledger,duplicates,trailingLigands,trailingReceptors,meter.used,warnings);
    }
    private static final class Meter {final long maximum;long used;Meter(long maximum){this.maximum=maximum;}void spend(long count){require(!Thread.currentThread().isInterrupted()&&count>=0&&count<=maximum-used,"Native operation capacity/cancellation reached; no partial output");used+=count;}}
    private static void label(String value){Objects.requireNonNull(value);require(!value.isEmpty()&&value.codePoints().noneMatch(c->c<32||c==127||c>=0xd800&&c<=0xdfff),"Empty/control/unpaired-surrogate identity; no normalization");}
    private static void gene(String value){label(value);require(!value.contains(":"),"Colon-delimited gene IDs are outside the unambiguous source key profile; no repair");}
    private static double[][] copy(double[][] source){Objects.requireNonNull(source);double[][] result=new double[source.length][];for(int i=0;i<source.length;i++)result[i]=Objects.requireNonNull(source[i]).clone();return result;}
    private static void require(boolean condition,String message){if(!condition)throw new IllegalArgumentException(message);}
}
